function App() {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState(null);
  useEffect(() => {
    const t = setTimeout(() => { setData('Dashboard data'); setLoading(false); }, 800);
    return () => clearTimeout(t);
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>/dashboard</h3>
      {loading
        ? <div style={{ background: '#eee', height: 24, borderRadius: 4 }}>Loading… (this is loading.tsx)</div>
        : <p>{data}</p>}
    </div>
  );
}

function App() {
  const [attempt, setAttempt] = useState(1);
  const failed = attempt < 2; // succeeds on the 2nd attempt
  const reset = () => setAttempt(a => a + 1);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>/dashboard (attempt {attempt})</h3>
      {failed ? (
        <div style={{ border: '1px solid #f5c2c7', background: '#f8d7da', padding: 12, borderRadius: 6 }}>
          <p><b>Something went wrong</b> — this is error.tsx</p>
          <button onClick={reset}>Try again (reset)</button>
        </div>
      ) : (
        <p>✅ Recovered after reset()!</p>
      )}
    </div>
  );
}

