// app/dashboard/error.tsx — with 'use client' at the very top of the file
function App() {
  // Simulates error.tsx({ error, reset }) as a Client Component
  const [recovered, setRecovered] = useState(false);
  const error = { message: 'Failed to load' };
  const reset = () => setRecovered(true);
  if (recovered) return <p style={{ fontFamily: 'system-ui', padding: 16 }}>✅ Recovered</p>;
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>{error.message}</p>
      <button onClick={reset}>Try again</button>
    </div>
  );
}

// app/products/[slug]/loading.tsx
export default function Loading() {
  return <div className="skeleton">Loading product…</div>;
}

// app/products/[slug]/error.tsx
'use client';
import { useEffect } from 'react';
export default function Error({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  useEffect(() => { console.error(error); }, [error]);
  return (
    <div>
      <p>Could not load this product.</p>
      <button onClick={() => reset()}>Try again</button>
    </div>
  );
}

// app/products/[slug]/page.tsx (Server Component)
import { notFound } from 'next/navigation';
export default async function Page({ params }: { params: { slug: string } }) {
  const product = await getProduct(params.slug);
  if (!product) notFound(); // renders not-found.tsx with a 404
  return <ProductView product={product} />;
}
